package ai.interviewiq.api.controller; import ai.interviewiq.api.dto.CatalogDtos.*; import ai.interviewiq.api.repository.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1") public class CatalogController {final CompanyRepository c;final JobRoleRepository r;final DifficultyLevelRepository d;final InterviewTemplateRepository t;public CatalogController(CompanyRepository c,JobRoleRepository r,DifficultyLevelRepository d,InterviewTemplateRepository t){this.c=c;this.r=r;this.d=d;this.t=t;}@GetMapping("/companies")List<CompanyResponse> companies(){return c.findByIsActiveTrueOrderByNameAsc().stream().map(x->new CompanyResponse(x.getId(),x.getCode(),x.getName())).toList();}@GetMapping("/job-roles")List<JobRoleResponse> roles(){return r.findByIsActiveTrueOrderByNameAsc().stream().map(x->new JobRoleResponse(x.getId(),x.getCode(),x.getName(),x.getCategory())).toList();}@GetMapping("/difficulty-levels")List<DifficultyResponse> difficulties(){return d.findByIsActiveTrueOrderByRankOrderAsc().stream().map(x->new DifficultyResponse(x.getId(),x.getCode(),x.getDisplayName(),x.getRankOrder())).toList();}}
